325	    /** The sheet's descendants: its children (the sheets naming it as their parent), their children,
326	     *  and so on, nearest first. Not dated: read from the live sheets. */
327	    public List<String> descendants(String sheetId) {
328	        java.util.Set<String> seen = new java.util.LinkedHashSet<>();
329	        seen.add(sheetId);
330	        java.util.ArrayDeque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
331	        while (!todo.isEmpty()) {
332	            for (String child : jdbc.query("SELECT sheet_id FROM PUBLIC.sheet_setting WHERE parent_id = ? ORDER BY sheet_id",
333	                    (rs, i) -> rs.getString("sheet_id"), todo.poll())) {
334	                if (seen.add(child)) todo.add(child);
335	            }
336	        }
337	        seen.remove(sheetId);
338	        return List.copyOf(seen);
339	    }
