341	    /** Whether the sheet `ancestor` is the sheet `sheetId` or one of its parents, any number of levels up. */
342	    public boolean isAncestor(String ancestor, String sheetId) {
343	        java.util.Set<String> seen = new java.util.HashSet<>();
344	        for (String sheet = sheetId; sheet != null && seen.add(sheet); sheet = parent(sheet)) {
345	            if (sheet.equals(ancestor)) return true;
346	        }
347	        return false;
348	    }
