562	    public BigDecimal noteThreshold(String sheetId, LocalDate date) {
563	        return valueOn(sheetId, NOTE_THRESHOLD, date, null);
564	    }
565	
566	    /** The sheet's review threshold in force on `date`: a claim dated then whose due is above it
567	     *  goes to REVIEW when opened, instead of OPEN. Null for none. */
568	    public BigDecimal reviewThreshold(String sheetId, LocalDate date) {
569	        return valueOn(sheetId, REVIEW_THRESHOLD, date, null);
570	    }
571	
572	    /** A person's due-total at most the sheet's cap less their cut total (not below 0.00); n/a (null)
573	     *  is not capped. */
574	    public BigDecimal capped(String sheetId, BigDecimal dueTotal, BigDecimal cutTotal) {
575	        BigDecimal cap = cap(sheetId);
576	        if (dueTotal == null || cap == null) return dueTotal;
577	        BigDecimal most = cap.subtract(cutTotal == null ? BigDecimal.ZERO : cutTotal).max(BigDecimal.ZERO).setScale(2);
578	        return dueTotal.compareTo(most) <= 0 ? dueTotal : most;
579	    }
