582	    public String permission(String sheetId, String action) {
583	        List<String> values = jdbc.query("SELECT roles FROM sheet_permission WHERE sheet_id = ? AND action_key = ?",
584	                (rs, i) -> rs.getString("roles"), sheetId, action);
