591	        jdbc.query("SELECT action_key, roles FROM sheet_permission WHERE sheet_id = ? AND roles IS NOT NULL",
592	                (RowCallbackHandler) rs -> perms.put(rs.getString("action_key"), rs.getString("roles")), sheetId);
593	        return perms;
594	    }
