597	    public void setPermission(String sheetId, String action, String roles) {
598	        jdbc.update("MERGE INTO sheet_permission (sheet_id, action_key, roles) KEY (sheet_id, action_key) VALUES (?, ?, ?)",
599	                sheetId, action, roles);
600	    }
