     *  {@link Figures#part}; a
     *  person's OPEN claims once today reaches their retirement date do not count, unless a statement
     *  binds them; a hold takes nothing out),
     *  n/a when there is no rate today and none has a figure, at most the sheet's cap less their cut total (not below 0.00; n/a is not
     *  capped); the sheet's skips the n/a ones, and its due and overdue totals leave out the single
     *  highest and lowest person's figure when three or more have one. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.onSheet(sheetId);
        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        List<Person> everyone = people.onSheet(sheetId);
        Map<Long, BigDecimal> cuts = pools.cutTotals(sheetId);
        // Each counting shared claim's holders' parts (each by the holder's own grade), by claim and holder;
        // a holder whose grade has no rate holds none (a part of 0.00).
        Map<Long, Map<Long, BigDecimal>> parts = new java.util.HashMap<>();
        for (Claim claim : all) {
            if (claim.getShares().isEmpty()) continue;
            Person owner = everyone.stream().filter(p -> p.getId() == claim.getPersonId()).findFirst().orElse(null);
            if (owner == null || !owner.counts(claim)) continue;
            Map<Long, BigDecimal> held = new java.util.HashMap<>();
            for (ClaimShare share : claim.getShares()) {
                Person holder = everyone.stream().filter(p -> p.getId() == share.personId()).findFirst().orElse(null);
                if (holder == null) continue;
                BigDecimal part = figures.part(claim, share, holder.gradeOn(claim.getDate()));
                if (part != null) held.put(share.personId(), part);
            }
            parts.put(claim.getId(), held);
        }
        for (Person person : everyone) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            BigDecimal settled = ZERO;
            int overdueCount = 0;
            boolean any = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()) continue;
                if (person.countsClaimed(claim) && claim.getCorrects() == null) claimed = claimed.add(claim.getAmount());
                if (!person.counts(claim)) continue;
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = figures.due(claim, grade);
                if (figures.overdue(claim, grade)) overdueCount++;
                if (figure != null && claim.getStatus() == ClaimStatus.SETTLED
                        && claim.getCorrects() == null) settled = settled.add(figure);
                if (figure != null) {
                    // Less the parts its share holders carry.
                    BigDecimal kept = figure;
                    for (BigDecimal part : parts.getOrDefault(claim.getId(), Map.of()).values()) kept = kept.subtract(part);
                    due = due.add(kept);
                    any = true;
                    if (figures.overdue(claim, grade)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // Their parts of the claims shared with them.
            for (Claim claim : all) {
                BigDecimal part = parts.getOrDefault(claim.getId(), Map.of()).get(person.getId());
                if (part == null) continue;
                due = due.add(part);
                any = true;
            }
            if (!any && rates.pct(sheetId, person.gradeOn(today), today) == null) due = null;
            due = settings.capped(sheetId, due, cuts.get(person.getId()));
            figuresOf.put(person.getId(), new Snapshot.PersonFigures(person.getName(), claimed, due, overdue,
                    settled.subtract(BigDecimal.valueOf(500L * overdueCount)).divide(HUNDRED, 0, RoundingMode.HALF_EVEN)));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) dues.add(due);
            overdues.add(overdue);
        }
        return new Snapshot(figuresOf, claimedTotal, trimmed(dues), trimmed(overdues));
    }

    /** The figures added up, leaving out the single highest and lowest when there are three or more. */
    private static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        sorted.sort(BigDecimal::compareTo);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        return sorted.stream().reduce(ZERO, BigDecimal::add);
    }

    /** Audit the figures that moved between `before` and the sheet now. */
    public void record(String sheetId, Snapshot before, String user) {
        record(sheetId, before, user, audit);
    }

    /** Audit the figures that moved between `before` and the sheet now, to the given audit. */
    public void record(String sheetId, Snapshot before, String user, Audit audit) {
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            Snapshot.PersonFigures was = before.people().get(id);
            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
                    && same(was.overdueTotal(), now.overdueTotal())) return;
            audit.record("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + show(now.claimed())
                    + " due-total=" + show(now.dueTotal()) + " overdue-total=" + show(now.overdueTotal()));
        });
        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
                || !same(before.overdueTotal(), after.overdueTotal())) {
            audit.record("TOTALS" + prefix + " claimed-total=" + show(after.claimedTotal())
                    + " due-total=" + show(after.dueTotal()) + " overdue-total=" + show(after.overdueTotal()));
        }
        BigDecimal threshold = settings.alertThreshold(sheetId);
        if (threshold == null) return;
        after.people().forEach((id, now) -> {
            Snapshot.PersonFigures was = before.people().get(id);
            if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
                audit.record("ALERT" + prefix + " name=" + now.name() + " due-total=" + show(now.dueTotal()));
            }
        });
    }

    /** Whether a due-total is above the threshold; n/a never is. */
    private static boolean above(BigDecimal dueTotal, BigDecimal threshold) {
        return dueTotal != null && dueTotal.compareTo(threshold) > 0;
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
            claim.setStated(bound);
            claim.setStatedDue(bound ? taken.bound().get(claim.getId()) : null);
            claims.save(claim);
        }
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(taken.dueTotal());
        person.setStatementDate(taken.date());
        people.saveStatement(person);
        statement.set(new Statement(taken.dueTotal(), taken.bound().size(), request.user(), date));
    }

    /** The statement of the person as the sheet stands (live, or as of a date): the figure each
     *  counting claim is bound to, by id, and their due-total as the sheet's figures work it out (see
     *  {@link Rollup#snapshot}: their parts of the claims shared with them, less the parts of their own
     *  claims that share holders carry), dated the sheet's today. */
    private static Taken work(Person person, Claims claims, Figures figures, Rates rates, Sheets sheets,
            Settings settings, Pools pools, Rollup rollup) {
        String sheetId = person.getSheetId();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean any = false;
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim claim : claims.ofPerson(sheetId, person.getId())) {
            if (person.counts(claim)) {
                // The statement binds the due as shown, late charge and floor included.
                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
                bound.put(claim.getId(), figure);
                if (figure != null) {
                    total = total.add(figure);
                    any = true;
                }
            }
        }
        LocalDate today = sheets.today(sheetId);
        Snapshot.PersonFigures figured = rollup.snapshot(sheetId).people().get(person.getId());
        if (figured != null) return new Taken(bound, figured.dueTotal(), today);
        BigDecimal dueTotal = !any && rates.pct(sheetId, person.gradeOn(today), today) == null ? null
                : settings.capped(sheetId, total, pools.cutTotals(sheetId).get(person.getId()));
        return new Taken(bound, dueTotal, today);
    }

    /** The date the statement is taken as of; null when none was given. */
    private static LocalDate asOfDate(StatementRequest request) throws InvalidSheetRequestException {
        String text = request.asOf();
        if (text == null || text.isBlank()) return null;
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + text);
        }
    }

    private record Taken(Map<Long, BigDecimal> bound, BigDecimal dueTotal, LocalDate date) {
    }
}
        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            // Figures.due: from the bound figure when a statement binds the claim (OPEN or PENDING), else live.
            due = figures.due(claim, grade);
            // Settled as of a date: frozen at its due as it stood at the end of that date.
            if (change.on() != null) due = change.onDue();
            // Before the clerk limit: a claim refused for want of a proof never goes PENDING.
            String judgedGrade = people.find(judged.getSheetId(), judged.getPersonId()).gradeOn(judged.getDate());
            BigDecimal judgedDue = judged == claim ? due : figures.due(judged, judgedGrade);
            BigDecimal threshold = settings.proofThreshold(judged.getSheetId(), judgedGrade, judged.getDate());
            if (threshold != null && judgedDue != null && judgedDue.compareTo(threshold) > 0 && judged.getProofs() == 0) {
                throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof");
            }
            if (threshold != null && judgedDue != null && judgedDue.compareTo(threshold) > 0) {
                for (String kind : settings.proofKinds(judged.getSheetId())) {
                    if (judged.proofsOf(kind) == 0) {
                        throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof of each kind: " + kind);
                    }
                }
            }
            // The person's grade's own limit on the sheet's today when one is set, else the sheet's.
            BigDecimal limit = settings.clerkLimit(claim.getSheetId(), grade);
            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
                    && java.util.EnumSet.of(Role.CLERK, Role.RESTRICTED).contains(settings.role(claim.getSheetId(), change.user()));
        }
        claim.setStatus(pending ? ClaimStatus.PENDING : review ? ClaimStatus.REVIEW : change.action().to());
        // Settled one at a time: in no batch (a bulk settle sets its batch after this).
        if (change.action() == ClaimAction.SETTLE) claim.setBatch(null);
        if (change.action() == ClaimAction.VOID) claim.setVoidReason(voidReason);
        if (change.action() == ClaimAction.OPEN) claim.setOpenedBy(change.user());
        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
            claim.setDue(due);
            // Numbered at settlement; a claim numbered already (before numbering moved here) keeps its number.
            if (claim.getNumber() == null) claim.setNumber(numbers.next(claim));
        }
    }
}

