/** The sheet's settings as the screen sees them, each dated one as in force on the sheet's today:
 *  the clerk limit with two decimals (null for no limit), the floor with two decimals, the terms in days, the late percent with two decimals, the policy date as set (yyyy-mm-dd, null when blank), the period numbering from (yyyy-mm-dd, null when off), the terms set per grade, by grade (a grade not in it uses the sheet's terms), the cap with two decimals (null for no cap), and the roles given, by user name;
 *  and every value recorded for the dated settings, by key, oldest from-date first; and the proof threshold
 *  with two decimals (null for none); and the permissions set, by action (roles comma separated; an action not in it keeps the standing rule); and the grace days (null when off); and every delegation of the steward role, oldest first; and the note threshold with two decimals (null for none); and the entry date (yyyy-mm-dd, null when off); and the grace days set per grade, by grade (a grade not in it has none); and the proof threshold set per grade with two decimals, by grade (a grade not in it uses the sheet's); and the pot with two decimals (null for none); and the parent sheet id (null for none); and the fiscal year start month (1 to 12); and the alert threshold with two decimals (null for off); and the rounding mode, half-up or half-even (null for none); and the review threshold with two decimals (null for none); and the escalation gap in days (null when off); and the review SLA in days (null for none); and the proof kinds, comma separated (null for none); and the default grade as set (null when blank: A); and the clerk limit set per grade with two decimals, by grade, in force on the sheet's today (a grade not in it uses the sheet's); and the mid and high score thresholds (null when unset); and whether the score log is on; and the maximum of open claims per person (null for none). */
public record SettingsResponse(String clerkLimit, String floor, int terms, String latePct, String policyDate, String periodNumberingFrom, Map<String, Integer> gradeTerms, String cap, List<RoleResponse> roles,
        Map<String, List<Settings.DatedValue>> dated, String proofThreshold, Map<String, String> perms, Integer graceDays,
        List<DelegationResponse> delegations, String noteThreshold, String entryDate, Map<String, Integer> gradeGrace, Map<String, String> gradeProof, String pot, String parent, int fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, Integer escalateAfter, Integer reviewSla, Integer pendingSla, String proofKinds, String defaultGrade, Map<String, String> gradeClerkLimit, Integer scoreMid, Integer scoreHigh, boolean scoreLog, Integer maxOpen) {
    public static SettingsResponse of(String sheetId, LocalDate today, Settings settings) {
        BigDecimal limit = settings.clerkLimit(sheetId);
        LocalDate policyDate = settings.policyDate(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        BigDecimal threshold = settings.proofThreshold(sheetId, today);
        BigDecimal noteThreshold = settings.noteThreshold(sheetId, today);
        BigDecimal reviewThreshold = settings.reviewThreshold(sheetId, today);
        LocalDate numberingFrom = settings.periodNumberingFrom(sheetId);
        LocalDate entryDate = settings.entryDate(sheetId);
        BigDecimal pot = settings.pot(sheetId);
        BigDecimal alert = settings.alertThreshold(sheetId);
        return new SettingsResponse(limit != null ? limit.toPlainString() : null,
                settings.floor(sheetId, today).toPlainString(), settings.terms(sheetId, today),
                settings.latePct(sheetId, today).toPlainString(),
                policyDate != null ? policyDate.toString() : null,
                numberingFrom != null ? numberingFrom.toString() : null, settings.gradeTerms(sheetId),
                cap != null ? cap.toPlainString() : null, settings.roles(sheetId), settings.dated(sheetId),
                threshold != null ? threshold.toPlainString() : null, settings.permissions(sheetId),
                settings.graceDays(sheetId), settings.delegations(sheetId),
                noteThreshold != null ? noteThreshold.toPlainString() : null,
                entryDate != null ? entryDate.toString() : null, settings.gradeGrace(sheetId), settings.gradeProof(sheetId),
                pot != null ? pot.toPlainString() : null, settings.parent(sheetId),
                settings.fiscalStartMonth(sheetId), alert != null ? alert.toPlainString() : null,
                settings.roundingName(sheetId, today),
                reviewThreshold != null ? reviewThreshold.toPlainString() : null, settings.escalateAfter(sheetId), settings.reviewSla(sheetId), settings.pendingSla(sheetId), settings.proofKindsValue(sheetId), settings.defaultGradeValue(sheetId), settings.gradeClerkLimit(sheetId),
                settings.scoreMid(sheetId), settings.scoreHigh(sheetId), settings.scoreLog(sheetId), settings.maxOpen(sheetId));
    }
}
