import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Late } from '../claims/useClaims';
import { useSheetToday } from '../sheet/useSheet';
import { useView, viewKey, viewPath } from '../asof/useAsOf';
import { gradeOn, usePeople } from '../people/usePeople';

/** A role given to a user name: clerk (the default for any name) or steward. */
export type RoleEntry = { name: string; role: string };

/** The sheet's settings as the server sends them: `clerkLimit` with two decimals, or null for no
 *  limit, `floor` with two decimals `terms` in days, `latePct` with two decimals and `policyDate` as
 *  set (yyyy-mm-dd), or null when blank: then the policy date is the sheet's today, and `periodNumberingFrom`
 *  (yyyy-mm-dd), or null when off, and `gradeTerms` the terms set per grade (a grade not in it uses the
 *  sheet's terms), and `cap` with two decimals, or null for no cap — each dated one as in force on the
 *  sheet's today; and `dated`, every value recorded for the dated settings by key (clerk-limit, floor,
 *  terms, terms-<grade>, grace-<grade>, late-pct, cap, proof-threshold, proof-threshold-<grade>, note-threshold, review-threshold, rounding), oldest from-date first; and `proofThreshold` with
 *  two decimals, or null for none, as in force on the sheet's today; and `perms`, the roles set for each
 *  action of the permission matrix, comma separated (an action not in it keeps the standing rule); and `graceDays`, the grace days, or null when off (not dated); and `delegations`, every delegation of the steward role, oldest first; and `noteThreshold` with two decimals, or null for none, as in force on the sheet's today; and `entryDate` (yyyy-mm-dd), or null when off: while set, the default date of a new claim in place of the sheet's today (not dated); and `gradeGrace`, the grace days set per grade in force on the sheet's today (a grade not in it has none; dated, under grace-<grade>); and `gradeProof`, the proof threshold set per grade with two decimals in force on the sheet's today (a grade not in it uses the sheet's; dated, under proof-threshold-<grade>); and `pot` with two decimals, or null for none: shared out among the members of each balanced pool (not dated); and `parent`, the parent sheet's id, or null for none: a grade with no rate in force on a date on this sheet takes the parent's then, up to three levels up (not dated); and `fiscalStartMonth`, the month (1 to 12) the sheet's fiscal year starts on: 1 unless set (not dated); and `rounding`, the rounding mode (half-up or half-even) in force on the sheet's today, or null for none: a claim dated when one is in force rounds its live figures by it, else by the policy date (dated); and `reviewThreshold` with two decimals, or null for none, as in force on the sheet's today: a claim whose due on its date is above the one then goes to REVIEW when opened (dated); and `escalateAfter`, the escalation gap in days, or null when off: reminding a claim whose previous reminder was at least that many days before the sheet's today escalates it, once per claim (not dated); and `reviewSla`, the review SLA in days, or null for none: a REVIEW claim whose review day plus it is before the sheet's today is review-late (not dated); and `pendingSla`, the pending SLA in days, or null for none: a PENDING claim whose pending day plus it is before the sheet's today is pending-late (not dated); and `proofKinds`, the sheet's proof kinds, comma separated (receipt, photo), or null for none: while set, a claim above the proof threshold needs a proof of each before it can be settled or approved (not dated); and `gradeClerkLimit`, the clerk limit set per grade with two decimals in force on the sheet's today (a grade not in it uses the sheet's; dated, under clerk-limit-<grade>): a claim's clerk limit is its person's grade's when set, else the sheet's. */
/** A delegation of the steward role: the user acts as a steward while the sheet's today is from
 *  `from` to `to` (yyyy-mm-dd, inclusive), for the steward `by` who delegated. */
export type DelegationEntry = { name: string; from: string; to: string; by: string };

export type Settings = { clerkLimit: string | null; floor: string; terms: number; latePct: string; policyDate: string | null; periodNumberingFrom: string | null; gradeTerms: Record<string, number>; cap: string | null; roles: RoleEntry[]; dated: Record<string, DatedValue[]>; proofThreshold: string | null; noteThreshold: string | null; perms: Record<string, string>; graceDays: number | null; delegations: DelegationEntry[]; entryDate: string | null; gradeGrace: Record<string, number>; gradeProof: Record<string, string>; pot: string | null; parent: string | null; fiscalStartMonth: number; alertThreshold: string | null; rounding: string | null; reviewThreshold: string | null; escalateAfter: number | null; reviewSla: number | null; pendingSla: number | null; proofKinds: string | null; defaultGrade: string | null; gradeClerkLimit: Record<string, string>; scoreMid: number | null; scoreHigh: number | null; scoreLog: boolean; maxOpen: number | null };

/** A dated setting's value from a from-date (yyyy-mm-dd); null for blank. */
export type DatedValue = { from: string; value: string | null };

/** The floor of a sheet that has not set one. */
export const DEFAULT_FLOOR = '1.00';

/** The terms, in days, of a sheet that has not set them. */
export const DEFAULT_TERMS = 14;

export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;

/** The sheet's settings, re-read whenever the sheet is loaded. */
export function useSettings(sheet: string) {
  const view = useView();
  return useQuery({
    queryKey: viewKey(settingsKey(sheet), view),
    queryFn: () => getJson<Settings>(viewPath(`/api/sheets/${encodeURIComponent(sheet)}/settings`, view)),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The value of a dated setting in force on `date`: the one with the latest from-date on or before
 *  it, else `start` (the setting's starting value; null when it has none). A blank value is null. */
export function valueOn(settings: Settings | undefined, key: string, date: string, start: string | null): string | null {
  let found: DatedValue | undefined;
  for (const v of settings?.dated?.[key] ?? []) if (v.from <= date) found = v;
  return found === undefined ? start : (found.value ?? start);
}

/** The sheet's floor in force on a date: a claim's live due is at least the one on its date. */
export type FloorOn = (date: string) => string;

/** The sheet's floor, by date. */
export function useFloor(sheet: string): FloorOn {
  const settings = useSettings(sheet).data;
  return (date) => valueOn(settings, 'floor', date, DEFAULT_FLOOR) ?? DEFAULT_FLOOR;
}

/** The sheet's cap in force on its today: a person's due-total is at most it. Null for no cap. */
export function useCap(sheet: string): string | null {
  const settings = useSettings(sheet).data;
  const today = useSheetToday(sheet);
  return today === '' ? (settings?.cap ?? null) : valueOn(settings, 'cap', today, null);
}

/** Whether a claim is review-late: REVIEW, and its review day (the sheet's today when it last went to
